mapper.select:
select count(*)
from kb_moderation_word_lists
where word = #{word}
  and category_code = #{categoryCode}

    and id <> #{excludeId}

mapper.insert:
insert into kb_moderation_word_lists (
    word, normalized_word, category_code, severity, lang, status, remark
) values (
    #{word}, #{normalizedWord}, #{categoryCode}, #{severity}, #{lang}, #{status}, #{remark}
)

mapper.update:
update kb_moderation_word_lists
set status = #{status}
where id = #{id}
  and is_deleted = 0
